    double mid = (a + b) / 2.0;
    double fmid = f(mid);
    double left_area = (mid - a) * (fa + fmid) / 2.0;
    double right_area = (b - mid) * (fmid + fb) / 2.0;

    if (std::abs(left_area + right_area - area) <= 3.0 * precision) {
        return left_area + right_area;
